/* Delete confirmation — native <dialog> modals are centered in the viewport by default */
.confirm { border: none; border-radius: 8px; padding: 1.5rem; max-width: min(90vw, 24rem); box-shadow: 0 10px 30px rgb(0 0 0 / 0.25); }
.confirm::backdrop { background: rgb(0 0 0 / 0.45); }
.confirm h2 { margin: 0 0 0.5rem; font-size: 1.25rem; }
.confirm p { margin: 0 0 1.25rem; }
.confirm-actions { display: flex; justify-content: flex-end; gap: 0.5rem; }
.confirm-actions button { padding: 0.5rem 1rem; border-radius: 6px; border: 1px solid #d1d5db; background: white; font: inherit; }
.confirm-actions .danger { background: #dc2626; border-color: #dc2626; color: white; }
.confirm-actions button:focus-visible { outline: 3px solid #1d4ed8; outline-offset: 2px; }

